                    JsonSerializer.Serialize(writer, templateObject.Components, jsonSerializerOptions);
                }
                else
                    writer.WriteNull("components");
            if (templateObject.VariablesOption.IsSet)
            {
                writer.WritePropertyName("variables");
                JsonSerializer.Serialize(writer, templateObject.Variables, jsonSerializerOptions);
            }
            if (templateObject.VariableDefaultsOption.IsSet)
            {
                writer.WritePropertyName("variableDefaults");
                JsonSerializer.Serialize(writer, templateObject.VariableDefaults, jsonSerializerOptions);
            }
            if (templateObject.UsageCountOption.IsSet)
                writer.WriteNumber("usageCount", templateObject.UsageCountOption.Value!.Value);

            if (templateObject.LastUsedAtOption.IsSet)
                writer.WriteString("lastUsedAt", templateObject.LastUsedAtOption.Value!.Value.ToString(LastUsedAtFormat));

            if (templateObject.MarketingTopicIdOption.IsSet)
                writer.WriteString("marketingTopicId", templateObject.MarketingTopicId);

            if (templateObject.AppendPreferencesLinkOption.IsSet)
                writer.WriteBoolean("appendPreferencesLink", templateObject.AppendPreferencesLinkOption.Value!.Value);

            if (templateObject.LocaleTranslationsOption.IsSet)
                if (templateObject.LocaleTranslationsOption.Value != null)
                {
                    writer.WritePropertyName("localeTranslations");
                    JsonSerializer.Serialize(writer, templateObject.LocaleTranslations, jsonSerializerOptions);
                }
                else
                    writer.WriteNull("localeTranslations");
            if (templateObject.CreatedAtOption.IsSet)
                writer.WriteString("createdAt", templateObject.CreatedAtOption.Value!.Value.ToString(CreatedAtFormat));

            if (templateObject.UpdatedAtOption.IsSet)
                writer.WriteString("updatedAt", templateObject.UpdatedAtOption.Value!.Value.ToString(UpdatedAtFormat));
        }
    }
}
